mapper.select:
select 
from community_report_case
where id = #{id} and reporter_member_id = #{reporterMemberId}

select 
from community_report_case
where reporter_member_id = #{reporterMemberId}
and stage = #{stage}
order by create_time desc, id desc

select r.id, r.target_type as targetType, r.target_id as targetId, r.reason_code as reasonCode, r.anonymity_policy as anonymityPolicy, r.stage, r.policy_version as policyVersion, r.reason_label_snapshot as reasonLabel, r.priority_snapshot as priority, r.first_response_minutes_snapshot as firstResponseMinutes, r.estimated_resolve_at as estimatedResolveAt, r.decision_summary as decisionSummary, r.version, r.create_time as createTime, first_response.firstResponseAt from community_report_case r left join ( select t.report_id as reportId, min(t.create_time) as firstResponseAt from community_report_timeline t where t.actor_type = 'PLATFORM' and t.event_type = 'STAGE_CHANGED' group by t.report_id ) first_response on first_response.reportId = r.id
r.stage = #{stage} and r.target_type = #{targetType}
order by r.create_time asc, r.id asc

mapper.update:
update community_report_case
set stage = #{nextStage}, version = version + 1, update_time = now()
where id = #{id} and stage = #{expectedStage} and version = #{expectedVersion}

mapper.select:
select 
from merchant_contribution
where contributor_member_id = #{contributorMemberId}
  and idempotency_key = #{idempotencyKey}
limit 1 for update

select 
from merchant_contribution
where contributor_member_id = #{contributorMemberId}
  and merchant_id = #{merchantId} and scope_key = #{scopeKey}
limit 1 for update

select 
from merchant_contribution
where id = #{id} and contributor_member_id = #{contributorMemberId}

select 
from merchant_contribution

    review_status = #{status}
    and merchant_id = #{merchantId}

order by create_time asc, id asc

mapper.update:
update merchant_contribution
set description = #{description}, evidence_asset_ids_json = #{evidenceAssetIdsJson},
    review_status = 'PENDING', review_reason = null, can_supplement = false,
    reviewed_by_user_id = null, reviewed_at = null,
    version = version + 1, update_time = #{updateTime}
where id = #{id} and review_status = #{expectedStatus} and version = #{expectedVersion}

update merchant_contribution
set review_status = 'MERGED', merged_at = now(), version = version + 1, update_time = now()
where id = #{id} and review_status = 'APPROVED' and version = #{expectedVersion}

