       external_ledger_no, credited_at, create_time, update_time
from merchant_contribution_reward_ledger where contribution_id = #{contributionId}

select 
from merchant_safety_rating
where member_id = #{memberId} and merchant_id = #{merchantId}
  and rating_period = #{ratingPeriod}
limit 1 for update
